mapper.update:
UPDATE products
name = #{name}, description = #{description}, price = #{price}, image_url = #{imageUrl}, category = #{category}, brand_id = #{brandId}, category_id = #{categoryId}, slug = #{slug}, title_i18n = #{titleI18n, typeHandler=com.example.backend.config.JsonNodeTypeHandler}, desc_i18n = #{descI18n, typeHandler=com.example.backend.config.JsonNodeTypeHandler}, meta_seo = #{metaSeo, typeHandler=com.example.backend.config.JsonNodeTypeHandler}, images = #{images, typeHandler=com.example.backend.config.JsonNodeTypeHandler}, status = #{status},
WHERE id = #{id}

mapper.select:
SELECT p.category AS "name", count(*) AS "count"

WHERE p.category IS NOT NULL AND p.category != ''
AND p.search_vector @@ plainto_tsquery('english', #{q})
AND p.price >= #{minPrice}
AND p.price <= #{maxPrice}
AND b.name IN
    #{brand}

GROUP BY p.category ORDER BY count(*) DESC

SELECT COUNT(*) FROM (
    SELECT p.id
    FROM products p
    LEFT JOIN (
        SELECT product_id, COALESCE(SUM(stock), 0) AS total_stock
        FROM product_skus
        GROUP BY product_id
    ) ps ON p.id = ps.product_id
    WHERE COALESCE(ps.total_stock, 0) <= #{threshold}
) low_stock
